"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[44292],{55073:e=>{e.exports=JSON.parse('{"id":"2026-08-27-viber-get-delete-template-endpoints","date":"2026-08-27","products":["Connect","APIs"],"product":"Connect","channel":"Viber","changeType":"Added","title":"Get and Delete Viber template endpoints","excerpt":"You can now retrieve and delete Viber message templates via API, in addition to creating them.","hasArticle":true,"bodyHtml":"<p>You can now retrieve and delete Viber message templates via API, in addition to creating them.</p>\\n<h2>Retrieve templates</h2>\\n<pre><code class=\\"language-http\\">GET /api/v1/accounts/{accountId}/channels/{channelId}/templates\\n</code></pre>\\n<p>Returns a <code>templates</code> array with one entry per template/language combination:</p>\\n<table>\\n<thead>\\n<tr>\\n<th>Field</th>\\n<th>Description</th>\\n</tr>\\n</thead>\\n<tbody><tr>\\n<td><code>templateId</code></td>\\n<td>Viber&#39;s internal identifier for the template.</td>\\n</tr>\\n<tr>\\n<td><code>name</code></td>\\n<td>The template name.</td>\\n</tr>\\n<tr>\\n<td><code>text</code></td>\\n<td>The template message text.</td>\\n</tr>\\n<tr>\\n<td><code>language</code></td>\\n<td>Language code for the template.</td>\\n</tr>\\n<tr>\\n<td><code>category</code></td>\\n<td>Template category (<code>Transactional</code> or <code>OTP</code>).</td>\\n</tr>\\n<tr>\\n<td><code>params</code></td>\\n<td>Parameter definitions used in the template text.</td>\\n</tr>\\n<tr>\\n<td><code>status</code></td>\\n<td>Current approval status with Viber: <code>Approved</code>, <code>Pending</code>, or <code>Rejected</code>.</td>\\n</tr>\\n<tr>\\n<td><code>createdAt</code> / <code>updatedAt</code></td>\\n<td>Timestamps for creation and last update.</td>\\n</tr>\\n</tbody></table>\\n<h2>Delete a template</h2>\\n<pre><code class=\\"language-http\\">DELETE /api/v1/accounts/{accountId}/channels/{channelId}/templates/{templateName}?language={language}\\n</code></pre>\\n<p>Because each language variant of a Viber template is stored as its own template, the <code>language</code> query parameter is required to identify which variant to delete. A successful deletion returns <code>200 OK</code> with an empty body; if the template/language pair doesn&#39;t exist, the endpoint returns <code>404 Not Found</code>.</p>\\n<p>Deleting templates is rate-limited to <strong>20 requests per minute per partner</strong>.</p>\\n<h2>Read more</h2>\\n<ul>\\n<li><a href=\\"/connect/docs/viber-templates-management\\">Viber Templates Management guide</a></li>\\n<li><a href=\\"/connect/reference/get-viber-templates\\">Get Viber templates \u2014 API reference</a></li>\\n<li><a href=\\"/connect/reference/delete-viber-template\\">Delete Viber template \u2014 API reference</a></li>\\n</ul>\\n"}')}}]);